export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed ?? 4.0;
  const g = inputs.gravity ?? 9.8;
  const tTop = u / g;
  const yTop = (u * u) / (2 * g);
  const dur = (2 * u) / g;
  const curTime = Math.min(Math.max(0, time), dur);
  const dt = curTime - tTop;

  const vToss = u - g * curTime;
  const aToss = -g;
  const yToss = u * curTime - 0.5 * g * curTime * curTime;

  let vDrop = 0;
  let aDrop = 0;
  let yDrop = yTop;
  let gateOpen = false;
  let dropState = "Held in place";

  if (curTime >= tTop) {
    gateOpen = true;
    aDrop = -g;
    vDrop = -g * dt;
    yDrop = yTop - 0.5 * g * dt * dt;
    dropState = Math.abs(curTime - tTop) < 0.001 ? "Just released" : "Falling together";
  }

  let tossState = "Rising";
  if (curTime === 0) tossState = "At launch";
  else if (Math.abs(curTime - tTop) < 0.001) tossState = "At the top";
  else if (curTime > tTop) tossState = curTime >= dur - 0.001 ? "At launch height" : "Falling";

  const objects = [];

  const tossPanel = sdk.panel({ x: 20, y: 30, w: 290, h: 360, title: "Toss Lane", state: tossState, id: "lane.toss" });
  const dropPanel = sdk.panel({ x: 330, y: 30, w: 290, h: 360, title: "Drop Lane", state: dropState, id: "lane.drop" });
  objects.push(...tossPanel, ...dropPanel);

  const yMinPx = 340;
  const yMaxPx = 90;
  const mapY = (yMeters) => yMinPx - (yMeters / 2.2) * (yMinPx - yMaxPx);

  objects.push(sdk.axis("axis.toss", { x: 50, y: yMinPx, length: yMinPx - yMaxPx, orientation: "y", min: 0, max: 2.2, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: "Height", unit: "m" }));
  objects.push(sdk.axis("axis.drop", { x: 360, y: yMinPx, length: yMinPx - yMaxPx, orientation: "y", min: 0, max: 2.2, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: "Height", unit: "m" }));

  const pyToss = mapY(Math.max(0, yToss));
  const pyDrop = mapY(Math.max(0, yDrop));
  const xToss = 185;
  const xDrop = 495;

  objects.push(sdk.gate("gate", xDrop, mapY(yTop), { open: gateOpen, w: 40, label: "Release Gate" }));

  const ghostY = mapY(yTop);
  objects.push(sdk.circle("ghost.toss", xToss, ghostY, 28, { role: "neutral", opacity: 0.3 }));
  objects.push(sdk.circle("ghost.drop", xDrop, ghostY, 28, { role: "neutral", opacity: 0.3 }));

  const ballToss = sdk.circle("ball.toss", xToss, pyToss, 28, { role: "learner" });
  const ballDrop = sdk.circle("ball.drop", xDrop, pyDrop, 28, { role: "prediction" });
  objects.push(ballToss, ballDrop);

  const vScale = 15;
  const aScale = 5;

  objects.push(...sdk.vector("vec.v.toss", { x: xToss - 18, y: pyToss }, { value: vToss, direction: "up" }, { scale: vScale, label: "v" }));
  objects.push(...sdk.vector("vec.a.toss", { x: xToss + 18, y: pyToss }, { value: aToss, direction: "up" }, { scale: aScale, label: "a" }));

  objects.push(...sdk.vector("vec.v.drop", { x: xDrop - 18, y: pyDrop }, { value: vDrop, direction: "up" }, { scale: vScale, label: "v" }));
  objects.push(...sdk.vector("vec.a.drop", { x: xDrop + 18, y: pyDrop }, { value: aDrop, direction: "up" }, { scale: aScale, label: "a" }));

  const linesToss = [`v: ${vToss.toFixed(2)} m/s`, `a: ${aToss.toFixed(2)} m/s²`];
  const linesDrop = [`v: ${vDrop.toFixed(2)} m/s`, `a: ${aDrop.toFixed(2)} m/s²`];
  objects.push(...sdk.callout(xToss + 32, pyToss - 20, linesToss, { id: "callout.toss" }));
  objects.push(...sdk.callout(xDrop + 32, pyDrop - 20, linesDrop, { id: "callout.drop" }));

  const frame = sdk.frame(objects);
  frame.width = 640;
  frame.height = 420;
  frame.readouts = [
    { id: "tossedVelocity", value: vToss },
    { id: "tossedAcceleration", value: aToss },
    { id: "dropVelocity", value: vDrop },
    { id: "dropAcceleration", value: aDrop }
  ];

  const quantities = {
    launchSpeed: u,
    gravity: g,
    apexTime: tTop,
    apexHeight: yTop,
    tossedVelocity: vToss,
    tossedAcceleration: aToss,
    tossedHeight: yToss,
    dropVelocity: vDrop,
    dropAcceleration: aDrop,
    dropHeight: yDrop
  };

  return { frame, quantities };
}
